_choice_arguments() {
    local word
    for word in "${argc__positionals[@]:0:${#argc__positionals[@]}-1}"; do
        if [[ "$word" != *=* ]]; then
            return 0
        fi
    done
    if [[ "${ARGC_CWORD:-}" == *=* ]]; then
        return 0
    fi
    _choice_recipe
    _choice_variable | _argc_util_transform suffix== nospace
}

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ -n "${argc__option:-}" ]]; then
        local -n values="$argc__option"
        argc__positionals=("${values[@]}")
    fi
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_group() {
    _helper_just --groups | gawk '
        /^[ \t]+[^ \t]/ {
            sub(/^[ \t]+/, "")
            print
        }
    '
}

_choice_module() {
    _helper_just --list --list-submodules --list-heading '' --color never | _helper_just_parse module
}

_choice_recipe() {
    _helper_just --list --list-submodules --list-heading '' --color never | _helper_just_parse recipe
}

_choice_set() {
    # --set takes VARIABLE then VALUE; only the variable name is enumerated.
    # argc_set includes the word being completed, so one element is the variable.
    if [[ ${#argc_set[@]} -gt 1 ]]; then
        return 0
    fi
    _choice_variable
}

_choice_variable() {
    _helper_just --variables | gawk '
        {
            for (i = 1; i <= NF; i++) print $i
        }
    '
}

# Run just with the justfile selection options already given on the line.
_helper_just() {
    local -a opts=()
    opts+=($(_argc_util_param_select_options --justfile --working-directory --global-justfile --ceiling --justfile-name))
    just "${opts[@]}" "$@" 2>/dev/null
}

# Parse `just --list --list-submodules` output. mode=recipe prints recipe
# paths and aliases with descriptions; mode=module prints module paths.
_helper_just_parse() {
    gawk -v mode="$1" '
    function trim(s) {
        sub(/^[ \t]+/, "", s)
        sub(/[ \t]+$/, "", s)
        return s
    }
    function path_of(depth, name,   i, p) {
        p = name
        for (i = depth - 1; i >= 0; i--) {
            if (i in mods) p = mods[i] "::" p
        }
        return p
    }
    function emit(name, desc) {
        if (desc == "") print name
        else printf "%s\t%s\n", name, desc
    }
    {
        if ($0 ~ /^[ \t]*$/) next
        if (!match($0, /[^ \t]/)) next
        line = substr($0, RSTART)
        depth = int((RSTART - 1) / 4) - 1
        if (depth < 0) depth = 0
        if (line ~ /^\[.*\]$/) next
        if (line ~ /:$/) {
            name = trim(substr(line, 1, length(line) - 1))
            if (name == "") next
            mods[depth] = name
            for (i = depth + 1; i in mods; i++) delete mods[i]
            if (mode == "module") emit(path_of(depth, name), "")
            next
        }
        if (mode != "recipe") next
        desc = ""
        p = index(line, " # ")
        if (p > 0) {
            desc = substr(line, p + 3)
            line = substr(line, 1, p - 1)
        }
        line = trim(line)
        if (line == "") next
        split(line, fields, /[ \t]+/)
        name = fields[1]
        count = 0
        if (desc ~ /\[alias: [^]]*\]$/) {
            match(desc, /\[alias: [^]]*\]$/)
            alias_part = substr(desc, RSTART + 8, RLENGTH - 9)
            desc = trim(substr(desc, 1, RSTART - 1))
            count = split(alias_part, aliases, /,[ \t]*/)
        }
        emit(path_of(depth, name), desc)
        for (i = 1; i <= count; i++) {
            if (aliases[i] != "") emit(path_of(depth, aliases[i]), desc)
        }
    }
    '
}
